attachments.text:
={{ (() => {
  const b = (s) => String.fromCharCode(42, 42) + s + String.fromCharCode(42, 42);
  const row = $json;
  const execUrl = 'https://n8n-mktg.corp-apps.com/workflow/' + $workflow.id + '/executions/' + $execution.id;
  return [
    b('Mode:') + ' ' + (row.sync_mode || ''),
    b('Tickets:') + ' ' + String(row.records_processed ?? ''),
    b('Checkpoint:') + ' ' + String(row.checkpoint ?? ''),
    b('Execution:') + ' [' + $execution.id + '](' + execUrl + ')',
    b('Completed:') + ' ' + $now.toISO()
  ].join('\n');
})() }}

assignments.value:
={{ (() => {
  const raw = $('Read MAP issues checkpoint').first().json.checkpoint;
  let checkpoint = DateTime.invalid('empty');
  if (raw) {
    const s = String(raw);
    const iso = DateTime.fromISO(s);
    const sql = DateTime.fromSQL(s);
    checkpoint = iso.isValid ? iso : (sql.isValid ? sql : DateTime.invalid('unparsed'));
  }
  if (!checkpoint.isValid) checkpoint = DateTime.now().minus({ hours: 2 });
  const start = checkpoint.minus({ minutes: 5 }).toFormat('yyyy-MM-dd HH:mm');
  const end = DateTime.now().toFormat('yyyy-MM-dd HH:mm');
  return `project = "Marketing Activity Plan" AND updated >= "${start}" AND updated < "${end}" ORDER BY updated ASC`;
})() }}

