={{ (() => {
  const b = (s) => String.fromCharCode(42, 42) + s + String.fromCharCode(42, 42);
  const jira = $('Get nightly Jira issue count').item.json.total;
  const db = $('Get Guardian MAP counts').item.json;
  const execUrl = 'https://n8n-mktg.corp-apps.com/workflow/' + $workflow.id + '/executions/' + $execution.id;
  return [
    b('Jira issues:') + ' ' + jira,
    b('Guardian issues:') + ' ' + db.db_issue_count,
    b('Issue time_spent:') + ' ' + db.db_issue_time_spent,
    b('Worklog seconds:') + ' ' + db.db_worklog_sum,
    b('Execution:') + ' [' + $execution.id + '](' + execUrl + ')',
    b('Completed:') + ' ' + $now.toISO()
  ].join('\n');
})() }}

